class Solution:
    def removeStones(self, stones: list[list[int]]) -> int:
        parent = {}
        def find(x):
            if x != parent.setdefault(x, x):
                parent[x] = find(parent[x])
            return parent[x]
        def union(a, b):
            parent[find(a)] = find(b)
        for r, c in stones:
            union(r, ~c)
        return len(stones) - len({find(r) for r, c in stones})

